export function isLocalBlobUrlCurrent(
  facts: LocalBlobUrlCurrentnessFacts,
): boolean {
  if (typeof facts.mediaElementMatches !== 'boolean'
    || typeof facts.sourceUrlMatches !== 'boolean'
    || typeof facts.bindingMatches !== 'boolean') {
    throw new Error('runtime-media-local-blob-url-currentness-mismatch');
  }
  return facts.mediaElementMatches
    && facts.sourceUrlMatches
    && facts.bindingMatches;
}

export function observeLocalBlobUrlCleanup(
  facts: LocalBlobUrlCleanupFacts,
): LocalBlobUrlCleanupObservation {
  if (typeof facts.blobUrlPresent !== 'boolean'
    || typeof facts.blobUrlRevoked !== 'boolean'
    || (!facts.blobUrlPresent && facts.blobUrlRevoked)) {
    throw new Error('runtime-media-local-blob-url-cleanup-mismatch');
